'use strict';

class InventoryError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends InventoryError {
  constructor(message) {
    super(message, 'VALIDATION');
  }
}

class UnknownSkuError extends InventoryError {
  constructor(sku) {
    super(`unknown sku: ${sku}`, 'UNKNOWN_SKU');
    this.sku = sku;
  }
}

class UnknownOrderError extends InventoryError {
  constructor(orderId) {
    super(`unknown order: ${orderId}`, 'UNKNOWN_ORDER');
    this.orderId = orderId;
  }
}

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};
'use strict';

module.exports = {
  ...require('./inventory'),
  ...require('./errors'),
  ...require('./store')
};
'use strict';

const { Store } = require('./store');
const { locksFor } = require('./locks');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. Each SKU and
 * each order has its own lock, shared by every service on the same store
 * object, so calls that touch the same SKU or order run one at a time and
 * calls that share neither run in parallel.
 */
class InventoryService {
  #locks;

  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    assertStore(store);
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.#locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.#locks.run([skuKey(sku)], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      const next = { ...item, stock: item.stock + qty };
      await this.store.set(skuKey(sku), next);
      return { sku, ...next };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copied before the first await, so a caller reusing its array cannot
    // change what gets held.
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    // The order lock makes a retry wait for the attempt in flight and then
    // find its order record.
    return this.#locks.run([orderKey(orderId)], async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      return this.#locks.run(lines.map(({ sku }) => skuKey(sku)), async () => {
        // Every item is checked before any is written, so a rejected order
        // holds nothing. Failures surface in list order, as they would if
        // the items were read one by one.
        const reads = await Promise.allSettled(lines.map(({ sku }) => this.getItem(sku)));
        const current = reads.map((read, i) => {
          if (read.status === 'rejected') {
            throw read.reason;
          }
          const { sku, qty } = lines[i];
          const free = read.value.stock - read.value.reserved;
          if (free < qty) {
            throw new InsufficientStockError(sku, qty, free);
          }
          return read.value;
        });
        const order = { orderId, items: lines, status: 'reserved', createdAt: this.now() };
        await this.#save(
          lines.map(({ sku, qty }, i) => ({
            key: skuKey(sku),
            before: current[i],
            after: { ...current[i], reserved: current[i].reserved + qty }
          })),
          { key: orderKey(orderId), before: undefined, after: order }
        );
        return toReservation(order);
      });
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#locks.run([orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return toReservation(await this.#settle(order, 'committed', sell));
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#locks.run([orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return toReservation(await this.#settle(order, 'released', unhold));
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    for (const key of await this.store.keys('order:')) {
      // One order at a time: the job holds at most one order lock, so it
      // never makes a checkout call wait longer than one release.
      const order = await this.store.get(key);
      if (isExpired(order, cutoff) && (await this.#releaseExpired(order.orderId, cutoff))) {
        released.push(order.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  // The first read in expire() took no lock, so a commit or release may
  // have landed since; check again under the order's lock.
  async #releaseExpired(orderId, cutoff) {
    return this.#locks.run([orderKey(orderId)], async () => {
      const order = await this.getOrder(orderId);
      if (!isExpired(order, cutoff)) {
        return false;
      }
      await this.#settle(order, 'released', unhold);
      return true;
    });
  }

  // Moves a reserved order to `status`, applying `change` to each of its
  // SKUs. The caller holds the order's lock.
  async #settle(order, status, change) {
    return this.#locks.run(order.items.map(({ sku }) => skuKey(sku)), async () => {
      const current = await Promise.all(order.items.map(({ sku }) => this.getItem(sku)));
      const next = { ...order, status };
      await this.#save(
        order.items.map(({ sku, qty }, i) => ({ key: skuKey(sku), before: current[i], after: change(current[i], qty) })),
        { key: orderKey(order.orderId), before: order, after: next }
      );
      return next;
    });
  }

  // Writes the SKU counters, then the order record. If any write fails,
  // every key is put back to the value it had, which is safe because the
  // caller still holds all of their locks. The store has no delete, so a
  // new order's record is not rolled back; its write comes last, so when it
  // fails the order does not exist.
  async #save(counters, order) {
    try {
      const writes = await Promise.allSettled(counters.map(({ key, after }) => this.store.set(key, after)));
      // Every write has settled before rollback starts, so a slow write
      // cannot land after its key has been restored.
      const failed = writes.find(({ status }) => status === 'rejected');
      if (failed) {
        throw failed.reason;
      }
      await this.store.set(order.key, order.after);
    } catch (error) {
      const restore = [...counters, order].filter(({ before }) => before !== undefined);
      const undo = await Promise.allSettled(restore.map(({ key, before }) => this.store.set(key, before)));
      const stuck = restore.filter((_, i) => undo[i].status === 'rejected');
      if (stuck.length > 0) {
        throw new AggregateError(
          [error, ...undo.filter(({ status }) => status === 'rejected').map(({ reason }) => reason)],
          `store write failed and rollback failed; check ${stuck.map(({ key }) => key).join(', ')}`
        );
      }
      throw error;
    }
  }
}

function sell(item, qty) {
  return { ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty };
}

function unhold(item, qty) {
  return { ...item, reserved: item.reserved - qty };
}

function isExpired(order, cutoff) {
  return order.status === 'reserved' && order.createdAt < cutoff;
}

function skuKey(sku) {
  return `sku:${sku}`;
}

function orderKey(orderId) {
  return `order:${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertStore(store) {
  if (!store || ['get', 'set', 'keys'].some(method => typeof store[method] !== 'function')) {
    throw new ValidationError('store must have get, set and keys methods');
  }
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

/**
 * FIFO mutexes keyed by string. A key has an entry only while it is held,
 * so the table stays as small as the set of keys in use.
 */
class KeyedLock {
  constructor() {
    // key -> callers waiting for it. A key is held while it is in the map.
    this.queues = new Map();
  }

  /** Number of keys currently held. */
  get size() {
    return this.queues.size;
  }

  /**
   * Run `fn` while holding every key in `keys`, releasing them once it
   * settles. Keys are taken one at a time in sorted order, so callers whose
   * key sets overlap cannot deadlock. A caller that nests `run` calls must
   * nest them in the same order everywhere (the service always takes an
   * order's lock before its SKUs' locks).
   */
# inventory-service

Stock reservations for checkout. `InventoryService` keeps three counters per
SKU (`stock`, `reserved`, `sold`) and moves each order from `reserved` to
`committed` or `released`. Every checkout worker calls it concurrently.

```js
const { InventoryService, InsufficientStockError } = require('./src');

const inventory = new InventoryService(); // or { store, reservationTtlMs, now }
await inventory.addStock('sneaker-limited', 250);

try {
  await inventory.reserve('order-123', [{ sku: 'sneaker-limited', qty: 1 }]);
  await inventory.commit('order-123');   // or release('order-123')
} catch (err) {
  if (err instanceof InsufficientStockError) {
    // sold out: err.sku, err.requested, err.available
  }
}

await inventory.expire(); // nightly: releases reservations older than the TTL
```

`store` can be anything with async `get(key)`, `set(key, value)` and
`keys(prefix)`. `src/store.js` is an in-memory version with the latency
profile of the production Redis cluster.

## INC-5521: what went wrong and what changed

| Symptom in ISSUE.md | Cause | Fix | Tests (`tests/incident.test.js`) |
| --- | --- | --- | --- |
| 263 orders confirmed for 250 units | Every counter update was a read-modify-write across two store round trips with nothing guarding it. Concurrent reserves read the same `reserved` value, all passed the stock check, and the last write won. `commit` and `addStock` lost updates the same way, which could also erase holds. | Per-SKU locks around every counter update. | `oversold stock: …` |
| `reserved` went negative and stayed there | `release()` did not check the order's status, so releasing a committed order subtracted its units from `reserved` a second time. `expire()` did not check status either and called `release()` on every old order, committed ones included. Concurrent releases of one order (a customer cancel racing `expire()`) each subtracted the units. | `release()` rejects a committed order with `OrderStateError`, as its doc comment says. `expire()` only releases orders that are still `reserved`, re-checked under the order's lock. Per-order locks make a second release a no-op. | `reserved went negative …` |
| A retried checkout held units twice | The idempotency check read the order record, but the record is only written at the end of `reserve()`. A retry that arrived while the first attempt was in flight found no record and held the stock again. The record then covered one hold, so the second hold was never returned. | `reserve()` holds the order's lock for the whole call, so a retry waits for the attempt in flight and then returns its reservation. | `a retried checkout held units twice …` |
| A rejected bundle left its other item held | `reserve()` wrote each item's hold before checking the next item. When a later item was out of stock (or unknown), the earlier holds had already been written, and no order record was written that could release them. | Every item is read and checked before anything is written. If a store write fails, the items already written are restored. | `a rejected bundle left its other item held` |
| `sold` higher than orders shipped | Overlapping commit retries both saw `reserved` and both added to `sold`. A commit racing `expire()` or a release could count the units as sold and also mark the order `released`, so it was never shipped. `expire()` also flipped committed orders to `released`. | Per-order locks and the status checks above. | `sold counts higher than orders shipped` |

`expire()` also used to list orders that were already released; it now
returns only the orders it released itself, as documented.

`flash-sale replay` in the same file runs a seeded random mix of all calls
across four services sharing one store. The store adds random latency. The
test then recomputes every counter from the order records.

## Concurrency model

- Every SKU and every order has its own FIFO lock (`src/locks.js`).
  `addStock` takes the SKU's lock. `reserve`, `commit` and `release` take the
  order's lock and then the locks of the order's SKUs.
- Calls that share no SKU and no order never wait for each other, so there is
  no service-wide lock. `available()` and `snapshot()` are single reads and
  take no lock.
- A call takes its SKU locks one at a time in sorted order, and the order's
  lock always comes before any SKU lock. That fixed order is why two bundles
  that list the same SKUs in different orders cannot deadlock.
- The lock table belongs to the store object, not the service. Several
  `InventoryService` instances built on one store (one per worker, say) lock
  against each other as well as against their own calls.
- A key is in the lock table only while it is held, so the table does not
  grow with the number of SKUs or orders and nothing needs cleaning up. The
  service has no timers or connections, so there is no `close()`.
- `expire()` releases one order at a time, holding at most one order's
  locks, so the nightly job adds no more delay to a checkout call than one
  release would.

### Trade-offs

- **Hot SKUs are serialized.** Every reserve on `sneaker-limited` runs one
  after another. That is the price of not overselling with a store that only
  has `get` and `set`. Each reserve holds the SKU's lock for three store
  round trips: read the counters, write them, write the order record.
- **A waiting bundle can hold some of its locks.** A bundle waiting for one
  of its SKUs already holds the SKU locks that sort before it, so another
  call on one of those SKUs waits too. That call shares a SKU with the
  bundle, so this does not break the rule above. Locks are FIFO, so no call
  starves.
- **Store failures.** If a store write fails, every key the call wrote is put
  back to the value it read, while the call still holds the locks, and the
  original error is rethrown. If a restore also fails, the call rejects with
  an `AggregateError` naming the keys to check. The store has no delete or
  transaction. If a write fails after the store actually applied it (for
  example, a timeout), the service cannot tell, and this rollback cannot
  make that case safe.

### Limits

The locks are in-process. They work for any number of services and workers
that share a store object in one Node.js process. That is the setup in which
the INC-5490 service-wide lock stopped the overselling in staging. Workers in
separate processes need atomic operations from the store itself, such as
Redis `WATCH`/`MULTI` or a Lua script per operation. The three-method store
interface does not offer those.

## Public API

Unchanged: the same methods, arguments, return values and error classes.
Two documented behaviours are now enforced:

- `release()` of a committed order rejects with `OrderStateError`.
- `expire()` never touches committed or released orders.

The constructor now throws `ValidationError` if `store` lacks `get`, `set`
or `keys`. Before, that failed later, on the first call.

## Tests

```sh
npm test
```

| File | Covers |
| --- | --- |
| `tests/inventory.test.js` | Original unit tests for each method |
| `tests/incident.test.js` | One reproduction per INC-5521 symptom, plus the randomized replay |
| `tests/locks.test.js` | `KeyedLock`: mutual exclusion, parallelism, FIFO, deadlock freedom, cleanup |
| `tests/edge-cases.test.js` | Calls on unrelated keys not waiting, rollback after store failures, boundaries, validation, unicode, caller input not mutated |

`tests/helpers.js` has the test stores:

- `GatedStore` stalls a call at a chosen key.
- `CountingStore` measures how many store calls are in flight at once.
- `FailingStore` injects store errors.
- `JitterStore` has random latency and no copying.

Of the 24 tests in `tests/incident.test.js`, 22 fail on the code before this
fix. The other two check behaviour that the fix had to keep.

