'use strict';

const assert = require('node:assert/strict');
const { InventoryService, Store } = require('../src');

async function seeded(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

// Calls on a gated key stall until the gate opens, which lets a test hold a
// call in the middle of its store round trips.
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  gate(key, methods = ['get', 'set']) {
    let open;
    let arrive;
    const opened = new Promise(resolve => { open = resolve; });
    const reached = new Promise(resolve => { arrive = resolve; });
    this.gates.set(key, { methods, opened, arrive });
    return {
      reached,
      open: () => {
        this.gates.delete(key);
        open();
      }
    };
  }

  async pass(method, key) {
    const gate = this.gates.get(key);
    if (gate && gate.methods.includes(method)) {
      gate.arrive();
      await gate.opened;
    }
  }

  async get(key) {
    await this.pass('get', key);
    return super.get(key);
  }

  async set(key, value) {
    await this.pass('set', key);
    return super.set(key, value);
  }
}

// Records the peak number of store calls in flight at once.
class CountingStore extends Store {
  constructor() {
    super();
    this.inFlight = 0;
    this.peak = 0;
  }

  async track(call) {
    this.inFlight += 1;
    this.peak = Math.max(this.peak, this.inFlight);
    try {
      return await call();
    } finally {
      this.inFlight -= 1;
    }
  }

  get(key) {
    return this.track(() => super.get(key));
  }

  set(key, value) {
    return this.track(() => super.set(key, value));
  }
}

// Fails the next matching call with the given error, once per failNext().
class FailingStore extends Store {
  constructor() {
    super();
    this.failures = [];
  }

  failNext(method, key, error = new Error(`injected ${method} failure on ${key}`)) {
    this.failures.push({ method, key, error });
    return error;
  }

  takeFailure(method, key) {
    const index = this.failures.findIndex(f => f.method === method && f.key === key);
    if (index !== -1) {
      const [failure] = this.failures.splice(index, 1);
      throw failure.error;
    }
  }

  async get(key) {
    this.takeFailure('get', key);
    return super.get(key);
  }

  async set(key, value) {
    this.takeFailure('set', key);
    return super.set(key, value);
  }
}

// Seeded PRNG (mulberry32) so a failing stress run can be replayed.
function random(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Plain Map store without cloning and with a random number of event-loop
// turns per call, so interleavings differ from the stock Store's.
class JitterStore {
  constructor(seed) {
    this.data = new Map();
    this.rand = random(seed);
  }

  jitter() {
    return turns(Math.floor(this.rand() * 4));
  }

  async get(key) {
    await this.jitter();
    return this.data.get(key);
  }

  async set(key, value) {
    await this.jitter();
    this.data.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

async function turns(n) {
  for (let i = 0; i < n; i++) {
    await new Promise(resolve => setImmediate(resolve));
  }
}

// Starts call(i) for i in [0, count), each `gap` event-loop turns after the
// previous one, the way a retry lands while the first attempt is in flight.
// The returned promises already have a rejection handler attached.
async function staggered(count, gap, call) {
  const started = [];
  for (let i = 0; i < count; i++) {
    if (i > 0) await turns(gap);
    started.push(settle(call(i)));
  }
  return Promise.all(started);
}

// Promise.allSettled for one promise, attached immediately so a rejection
// before the caller awaits it is not reported as unhandled.
function settle(promise) {
  return promise.then(
    value => ({ status: 'fulfilled', value }),
    reason => ({ status: 'rejected', reason })
  );
}

// Rejects if `promise` has not settled within `ms`, so a call that waits on
// an unrelated lock fails the test instead of hanging it.
function within(promise, ms, what) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} did not settle within ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

// Recomputes every SKU's reserved and sold counts from the order records and
// checks them, and stock, against the counters.
async function assertConsistent(svc, store, added) {
  const orders = await Promise.all((await store.keys('order:')).map(key => store.get(key)));
  for (const [sku, units] of Object.entries(added)) {
    let reserved = 0;
    let sold = 0;
    for (const order of orders) {
      const line = order.items.find(item => item.sku === sku);
      if (line && order.status === 'reserved') reserved += line.qty;
      if (line && order.status === 'committed') sold += line.qty;
    }
    const snap = await svc.snapshot(sku);
    assert.deepEqual(snap, { sku, stock: units - sold, reserved, sold }, `counters for ${sku}`);
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku} went negative`);
  }
}

module.exports = {
  seeded,
  GatedStore,
  CountingStore,
  FailingStore,
  JitterStore,
  random,
  turns,
  staggered,
  settle,
  within,
  assertConsistent
};
