      ...Array.from({ length: 20 }, () => svc.adjustStock('a', 2, COUNT)),
      ...Array.from({ length: 10 }, () => svc.adjustStock('a', -3, COUNT)),
      ...Array.from({ length: 5 }, () => svc.addStock('a', 1))
    ]);
    assert.equal((await svc.snapshot('a')).stock, 100 + 40 - 30 + 5);
  });

  it('cannot take stock below reserved when racing reserves', async () => {
    const svc = await seeded({ a: 10 });
    const calls = [
      ...Array.from({ length: 10 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'a', qty: 1 }])),
      ...Array.from({ length: 10 }, () => svc.adjustStock('a', -1, COUNT))
    ].map(settle);
    const results = await Promise.all(calls);
    for (const r of results) {
      if (r.status === 'rejected') assert.ok(r.reason instanceof InsufficientStockError);
    }
    const snap = await svc.snapshot('a');
    assert.ok(snap.stock >= snap.reserved, JSON.stringify(snap));
    const reserved = results.slice(0, 10).filter(r => r.status === 'fulfilled').length;
    const removed = results.slice(10).filter(r => r.status === 'fulfilled').length;
    assert.deepEqual(snap, { sku: 'a', stock: 10 - removed, reserved, sold: 0 });
  });

  it('waits for a reserve in flight on the same sku, then sees its hold', async () => {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('a', 5);
    const gate = store.gate('sku:a', ['set']);
    const reserve = settle(svc.reserve('o1', [{ sku: 'a', qty: 4 }]));
    await gate.reached;
    const adjust = settle(svc.adjustStock('a', -2, COUNT));
    gate.open();
    assert.equal((await reserve).status, 'fulfilled');
    const result = await adjust;
    assert.equal(result.status, 'rejected');
    assert.ok(result.reason instanceof InsufficientStockError);
    assert.equal(result.reason.available, 1);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 4, sold: 0 });
  });

  it('does not block calls on other skus while stalled', async () => {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('hot', 5);
    await svc.addStock('cold', 5);
    const gate = store.gate('sku:hot', ['set']);
    const stalled = settle(svc.adjustStock('hot', 1, COUNT));
    await gate.reached;
    await within(svc.adjustStock('cold', -1, COUNT), 1000, 'adjustStock on cold');
    await within(svc.reserve('o1', [{ sku: 'cold', qty: 1 }]), 1000, 'reserve on cold');
    gate.open();
    assert.equal((await stalled).status, 'fulfilled');
  });

  it('shares locks across services on one store', async () => {
    const store = new GatedStore();
    const a = new InventoryService({ store });
    const b = new InventoryService({ store });
    await a.addStock('x', 10);
    const gate = store.gate('sku:x', ['set']);
    const first = settle(a.adjustStock('x', 5, COUNT));
    await gate.reached;
    const second = settle(b.adjustStock('x', -3, COUNT));
    gate.open();
    await Promise.all([first, second]);
    assert.equal((await a.snapshot('x')).stock, 12);
  });

  it('keeps counters consistent in a randomized mix with reserve, commit and release', async () => {
    for (const seed of [1, 2, 3]) {
      const store = new JitterStore(seed);
      const workers = Array.from({ length: 3 }, () => new InventoryService({ store }));
      const rand = random(seed * 977);
      await workers[0].addStock('a', 20);
      await workers[0].addStock('b', 20);
      let added = { a: 20, b: 20 };
      const adjustments = [];
      const ops = [];
      for (let i = 0; i < 60; i++) {
        const svc = workers[i % 3];
        const sku = rand() < 0.5 ? 'a' : 'b';
        const roll = rand();
        if (roll < 0.35) {
          const delta = (rand() < 0.5 ? -1 : 1) * (1 + Math.floor(rand() * 4));
          ops.push(settle(svc.adjustStock(sku, delta, COUNT)).then(r => {
            if (r.status === 'fulfilled') adjustments.push([sku, delta]);
            else assert.ok(r.reason instanceof InsufficientStockError);
          }));
        } else {
          const id = `o${i}`;
          ops.push((async () => {
            const held = await settle(svc.reserve(id, [{ sku, qty: 1 + Math.floor(rand() * 3) }]));
            if (held.status === 'rejected') return assert.ok(held.reason instanceof InsufficientStockError);
            await (roll < 0.7 ? svc.commit(id) : svc.release(id));
          })());
        }
      }
      await Promise.all(ops);
      added = { ...added };
      for (const [sku, delta] of adjustments) added[sku] += delta;
      await assertConsistent(workers[0], store, added);
    }
  });
});
